fn is_even_at_index_even(lst: &Vec<i32>) -> bool {
    // Iterate over all even indices (0, 2, 4, ...)
    let mut idx = 0;
    while idx < lst.len() {
        // If the element at an even index is not even, return false
        if lst[idx] % 2 != 0 {
            return false;
        }
        idx += 2;
    }
    // If we never found a violation, return true
    true
}

